FUNCTION_BLOCK JamPumpControl
VAR_INPUT
    VISCOSITY_OK    : BOOL;
    PASTE_E_STOP_NC : BOOL;
    DebounceTime    : TIME;
    CycleTime       : TIME;
END_VAR
VAR_OUTPUT
    VFD_RUN         : BOOL;
    PUMP_MAINT_DUE  : BOOL;
    PUMP_RUNTIME_ACC: LTIME;
END_VAR
VAR
    viscosity_valid : BOOL := FALSE;
    DebounceTimer   : TON;
    prevEStop       : BOOL := TRUE;   // holds previous cycle state of emergency stop
    init            : BOOL := TRUE;   // power‑up initialization flag
