    VFD_RUN          := FALSE;
    PUMP_RUNTIME_ACC := LTIME#0;
    PUMP_MAINT_DUE   := FALSE;
    viscosity_valid  := FALSE;
    // Make sure the debounce timer is reset
    DebounceTimer(IN := FALSE, PT := DebounceTime);
    // Initialise the previous E‑Stop state to the present value
    // so that a spurious falling edge is not generated on the first scan.
    prevEStop := PASTE_E_STOP_NC;
    init := FALSE;
ELSE
