    // Emergency‑stop edge detection
    // ---------------------------------------------------
    IF (NOT PASTE_E_STOP_NC) AND prevEStop THEN
        // Emergency stop has been activated – clear the viscosity permissive
        // and abort any in‑progress debounce timing.
        viscosity_valid         := FALSE;
        DebounceTimer(IN := FALSE);
    END_IF
    prevEStop := PASTE_E_STOP_NC;

    // ---------------------------------------------------
    // Viscosity condition – immediate invalidation on loss of signal
    // ---------------------------------------------------
    IF NOT VISCOSITY_OK THEN
        viscosity_valid := FALSE;
    END_IF

    // ---------------------------------------------------
    // Debounce timer
    // ---------------------------------------------------
    // Start timing only when the raw signal is true, we do not yet have a
    // valid reading and the emergency stop circuit is closed.
